  function loadAtlasEngine(){if(window.DMZAtlasGuideEngine)return Promise.resolve(window.DMZAtlasGuideEngine);if(!atlasEnginePromise)atlasEnginePromise=new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='/js/ocean-atlas-guide-engine.js?v=20261013-guides3';script.onload=()=>window.DMZAtlasGuideEngine?resolve(window.DMZAtlasGuideEngine):reject(new Error('Atlas engine unavailable.'));script.onerror=()=>{atlasEnginePromise=null;reject(new Error('Atlas engine unavailable.'));};document.head.append(script);});return atlasEnginePromise;}
