  async function save(row){ const ticket=epoch; const payload={...row.data,id:row.id,updatedAt:new Date().toISOString()}; const result=await request(`/api/account/sync/plan/${encodeURIComponent(row.id)}`,{method:'PUT',body:JSON.stringify({baseRevision:row.revision||0,mutationId:crypto.randomUUID(),deleted:!!row.deleted,data:payload})}); if(ticket!==epoch)throw new Error('The account changed. Please sign in again.'); records.set(key(result.record),result.record); return result.record; }
  async function load(force=false){
    if(!request||!userId||loading||(loaded&&!force))return;
    const ticket=epoch; status('Loading your plans, gear, and logbook…');
    const task=(async()=>{
      let after='',rows=[];
      do {
        const page=await request(`/api/account/sync?include=plan,gear,setup,dive${after?`&after=${encodeURIComponent(after)}`:''}`);
        if(ticket!==epoch)return;
        rows.push(...page.records);after=page.next;status(`Loading planner · ${rows.length} records received…`);
      }while(after);
      records=new Map(rows.filter((r)=>r.data&&!r.deleted).map((r)=>[key(r),r]));loaded=true;render();
      status(`Planner refreshed at ${new Date().toLocaleTimeString([],{hour:'numeric',minute:'2-digit'})}.`);
    })().catch((error)=>{if(ticket===epoch)status(error.message||'Planner data could not load.',true);}).finally(()=>{if(loading===task)loading=null;});
    loading=task;return task;
  }
